BEGIN;
CREATE TABLE IF NOT EXISTS professional_availability(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,professional_id uuid NOT NULL REFERENCES professional_profiles(id) ON DELETE CASCADE,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at),UNIQUE(professional_id,starts_at,ends_at));
ALTER TABLE professional_availability ENABLE ROW LEVEL SECURITY;ALTER TABLE professional_availability FORCE ROW LEVEL SECURITY;CREATE POLICY professional_availability_tenant_isolation ON professional_availability USING(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);GRANT SELECT,INSERT,UPDATE,DELETE ON professional_availability TO app_runtime;COMMIT;
